/**
 * @name Remote input to filesystem write operations
 * @description Detect flows from RemoteFlowSource into write-mode file open calls within psutil package.
 * @kind path-problem
 * @problem.severity error
 * @id py/psutil/remote-to-file-write
 * @tags security
 *       external/cwe/cwe-073
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module PsutilFsWriteConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) { source instanceof RemoteFlowSource }

  predicate isSink(DataFlow::Node sink) {
    exists(Call call, Expr arg, Expr modeArg |
      call = sink.asExpr() and
      call.getFunc().(Name).getId() = "open" and
      // first argument is the path
      arg = call.getArg(0) and
      // ensure mode suggests writing if present
      (
        not exists(call.getArg(1)) or
        modeArg = call.getArg(1) and
        modeArg.toString().regexpMatch(".*[wax].*")
      )
    )
  }
}

module PsutilFsWriteFlow = TaintTracking::Global<PsutilFsWriteConfig>;
import PsutilFsWriteFlow::PathGraph

from PsutilFsWriteFlow::PathNode source, PsutilFsWriteFlow::PathNode sink
where PsutilFsWriteFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Remote-controlled data reaches a file path used for writing $@.", source.getNode(), "remote input"
